        [UnityTest] public IEnumerator P6GreenBridgeWholeArmyResetAndResourceBudget()
        {
            Assert.AreEqual(2048,m.Buffers.AgentCount);Assert.IsNull(m.LocalOrders);Assert.IsTrue(m.TryEnableLocalOrderPrototype(out var error),error);var local=m.LocalOrders;int epoch=local.Epoch;
            var r=local.Submit(epoch,0,1,Enumerable.Range(0,32).ToArray(),LocalOrderKind.Hold,Vector2.zero);yield return Wait(r);yield return WaitGpu(r);
            long cpuBytes=local.NavigationCpuUpperEstimate;
            var positions=new Vector2[2048];m.Buffers.agentPositionReadBuffer.GetData(positions);Vector2 center=Vector2.zero;for(int i=0;i<32;i++)center+=positions[i]/32f;
            Vector2 target=Vector2.zero;bool found=false;foreach(var offset in new[]{new Vector2(-20,0),new Vector2(20,0),new Vector2(0,20),new Vector2(0,-20)})
            {var candidate=center+offset;if(!m.TerrainNavigation.TryGetCell(candidate,out int cell))continue;candidate=m.TerrainNavigation.CellCenter(cell);if(m.TerrainNavigation.IsFootprintWalkable(candidate,new Vector2(12,12))&&Enumerable.Range(0,32).All(i=>m.TerrainNavigation.AreConnected(positions[i],candidate))){target=candidate;found=true;break;}}
            Assert.IsTrue(found,"Fixture needs a reachable destination for 32 members");var move=local.Submit(epoch,0,11,Enumerable.Range(0,32).ToArray(),LocalOrderKind.Move,target);yield return Wait(move);yield return WaitGpu(move);

            Assert.IsTrue(c.IssueOrder(ArmyOrder.Hold(0)));Assert.AreEqual(0,local.ActiveGroups);Assert.AreEqual(0,local.ActiveMembers);
            var pending=local.Submit(epoch,0,2,new[]{0},LocalOrderKind.Hold,Vector2.zero);m.ResetScenario();Assert.AreEqual(LocalOrderStatus.Invalidated,pending.Status);Assert.IsNull(m.LocalOrders);Assert.AreEqual(0,local.GpuBytes);
            Assert.IsTrue(m.TryEnableLocalOrderPrototype(out error),error);Assert.AreNotEqual(epoch,m.LocalOrders.Epoch);Assert.AreEqual(LocalOrderStatus.Rejected,m.LocalOrders.Submit(epoch,0,3,new[]{0},LocalOrderKind.Hold,Vector2.zero).Status);
            string text="2048 Green;FlowCellCount="+m.Buffers.FlowCellCount+";groups=4+1 staging;GPU bytes="+m.LocalOrders.GpuBytes+";first plan worker ms="+r.PlanMilliseconds+";cached move solve ms="+move.PlanMilliseconds+";move upload ms="+move.UploadMilliseconds+";move snapshot ms="+move.ReadbackMilliseconds+";snapshot ms="+r.ReadbackMilliseconds+";upload ms="+r.UploadMilliseconds+";CPU cache upper bytes="+cpuBytes+";whole-army clears;reset invalidates;new epoch rejects old";
            File.WriteAllText(Path.Combine(output,"p6-green-resources.txt"),text);Debug.Log(text);
